const tenDigits = (raw) => {
  const d = String(raw || "").replace(/\D/g, "");
  return d.length >= 10 ? d.slice(-10) : null;
};

async function main() {
  const { PrismaClient } = require("@st-michael/database");
  const prisma = new PrismaClient();
  try {
    const brokers = await prisma.broker.findMany({ select: { id: true, phone: true } });
    const extra = await prisma.brokerPhone.findMany({ select: { brokerId: true, phone: true } });
    const known = new Set();
    for (const b of brokers) { const t = tenDigits(b.phone); if (t) known.add(t); }
    for (const p of extra) { const t = tenDigits(p.phone); if (t) known.add(t); }

    const toCreate = [];
    const stat = { всего: ROWS.length, ужеЕсть: 0, кСозданию: 0, безТелефона: 0, созданоШт: 0, ошибок: 0 };
    for (const row of ROWS) {
      const ten = tenDigits(row.phone);
      if (!ten) { stat.безТелефона++; continue; }
      if (known.has(ten)) { stat.ужеЕсть++; continue; }
      known.add(ten);
      stat.кСозданию++;
      toCreate.push(row);
    }

    console.log("=== Брокеры старого кабинета ===");
    for (const [k, v] of Object.entries(stat)) if (k !== "созданоШт" && k !== "ошибок") console.log(`  ${k.padEnd(14)} ${v}`);
    const byYear = {};
    for (const r of toCreate) { const y = String(r.registeredAt || "").slice(0, 4) || "—"; byYear[y] = (byYear[y] || 0) + 1; }
    console.log("  к созданию по годам регистрации:", JSON.stringify(byYear));
    console.log("  примеры:");
    for (const r of toCreate.slice(0, 5)) console.log(`    ${r.fullName} · ${r.phone.slice(0, 5)}***${r.phone.slice(-2)} · ${r.agencyRaw || "без агентства"}`);

    if (!WRITE) {
      console.log("\nПРОГОН БЕЗ ЗАПИСИ: база не изменена (нужны DRY_RUN=0 и CONFIRM=1).");
      return;
    }
    for (const r of toCreate) {
      try {
        await prisma.broker.create({
          data: {
            phone: r.phone,
            fullName: r.fullName,
            displayName: r.fullName,
            displayNameSource: "old_cabinet",
            email: r.email || null,
            status: "PENDING",
            role: "BROKER",
            isInBase: true,
            baseSource: "old_cabinet",
            createdAt: r.registeredAt ? new Date(r.registeredAt) : undefined,
            notes: r.agencyRaw ? `Старый кабинет, агентство в источнике: ${r.agencyRaw}` : "Старый кабинет",
          },
        });
        stat.созданоШт++;
      } catch (e) {
        stat.ошибок++;
        if (stat.ошибок <= 5) console.error(`    ошибка по ${r.phone.slice(0, 5)}***: ${e?.message || e}`);
      }
    }
    console.log(`\nЗАПИСЬ ВЫПОЛНЕНА: создано ${stat.созданоШт}, ошибок ${stat.ошибок}`);
  } finally {
    await prisma.$disconnect();
  }
}
main().catch((e) => { console.error("FATAL:", e?.message || e); process.exit(1); });
